// Build: prompts.js -> worker/src/prompts.gen.js. Run after any edit to prompts.js: node build.mjs
// The page (docs/) needs no build. Its relay address is in docs/config.js.
import fs from "node:fs";
import { createRequire } from "node:module";
const require = createRequire(import.meta.url);
const { COACH, STEPS, DATA, SCHEMAS } = require("./prompts.js");
const dash = /[–—]/;
for (const [k, t] of Object.entries({ COACH, DATA, ...STEPS })) if (dash.test(t)) throw new Error("en or em dash in " + k);
fs.writeFileSync(new URL("./worker/src/prompts.gen.js", import.meta.url),
  "// GENERATED by build.mjs from prompts.js. Edit prompts.js, then run: node build.mjs\n" +
  `export const COACH = ${JSON.stringify(COACH)};\nexport const DATA = ${JSON.stringify(DATA)};\n` +
  `export const STEPS = ${JSON.stringify(STEPS, null, 1)};\nexport const SCHEMAS = ${JSON.stringify(SCHEMAS)};\n`);
console.log("built worker/src/prompts.gen.js");
